            rd3_rrr_a(2, 3, 3) = rd3_rrr_a(2, 3, 3) + t_rd3_rrr_a_122
            rd3_rrr_a(3, 2, 3) = rd3_rrr_a(3, 2, 3) + t_rd3_rrr_a_122
            rd3_rrr_a(3, 3, 2) = rd3_rrr_a(3, 3, 2) + t_rd3_rrr_a_122
            rd3_rrr_a(3, 3, 3) = &
               rd3_rrr_a(3, 3, 3) + (3.0_wp*d_a(3)*e_a(1)*x17*x5 + 3.0_wp*e_a(2)*x26*x41*x7 - &
               3.0_wp*x21 - x25*x41 - 3.0_wp*x27*x41 - 3.0_wp*x31)
         end block
      end select

   end subroutine cfc_atomic_radius_eval_faded

   pure module subroutine cfc_pair_radius_eval_faded(d_a, d_b, R_a, R_b, a2, c_par, fade_start, &
                                              fade_width, max_deriv, rd0_a, rd0_b, rd1_r_a, &
                                              rd1_r_b, rd2_rr_a, rd2_rr_b, rd3_rrr_a, rd3_rrr_b, &
                                              sg_a, sg_b)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Displacement r - r_b
      real(wp), intent(in) :: d_b(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Radius of atom b
      real(wp), intent(in) :: R_b
      !> Pair-term exponent prefactor a2 (Diedenhofen-Klamt 2018: -9)
      real(wp), intent(in) :: a2
      !> Pair-term coupling constant c (Diedenhofen-Klamt 2018: 5)
      real(wp), intent(in) :: c_par
      !> Fade onset in sigma = ||d||/R - 1, as passed to the strip kernel; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width in sigma, finite and > 0 (read only when a center is past fade_start)
      real(wp), intent(in) :: fade_width
      !> Highest spatial-derivative order to accumulate (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> d/dR_a of the order-0 spatial derivative; R_a is atom a's radius, so there is no trailing
      !> nuclear index
      real(wp), intent(inout) :: rd0_a
      !> d/dR_b of the order-0 spatial derivative; R_b is atom b's radius, so there is no trailing
      !> nuclear index
      real(wp), intent(inout) :: rd0_b
      !> d/dR_a of the order-1 spatial derivative; R_a is atom a's radius, so there is no trailing
      !> nuclear index
      real(wp), intent(inout) :: rd1_r_a(3)
      !> d/dR_b of the order-1 spatial derivative; R_b is atom b's radius, so there is no trailing
      !> nuclear index
      real(wp), intent(inout) :: rd1_r_b(3)
      !> d/dR_a of the order-2 spatial derivative; R_a is atom a's radius, so there is no trailing
      !> nuclear index
      real(wp), intent(inout) :: rd2_rr_a(3, 3)
      !> d/dR_b of the order-2 spatial derivative; R_b is atom b's radius, so there is no trailing
      !> nuclear index
      real(wp), intent(inout) :: rd2_rr_b(3, 3)
      !> d/dR_a of the order-3 spatial derivative; R_a is atom a's radius, so there is no trailing
      !> nuclear index
      real(wp), intent(inout) :: rd3_rrr_a(3, 3, 3)
      !> d/dR_b of the order-3 spatial derivative; R_b is atom b's radius, so there is no trailing
      !> nuclear index
      real(wp), intent(inout) :: rd3_rrr_b(3, 3, 3)
      !> Reduced distance sigma = ||d_a||/R_a - 1 of center a
      real(wp), intent(in) :: sg_a
      !> Reduced distance sigma = ||d_b||/R_b - 1 of center b
      real(wp), intent(in) :: sg_b

      !> Fade: band end, reciprocal width, raw and clamped s, t, ds/dsigma
      real(wp) :: band_end, inv_delta, sr, fs, ft, dsdd
      !> d^j P_n/ds^j of the reduced smoothstep polynomial, w = s**(n+1) P_n(s)
      real(wp) :: fp0, fp1, fp2, fp3, fp4
      !> Powers s**k of the fade variable
      real(wp) :: fsp1, fsp2, fsp3, fsp4, fsp5
      !> Unfaded factor exp(a2 (sigma_a + sigma_b)), on g_a
      real(wp) :: fu
      !> Faded radial factor and its sigma derivatives d^j/dsigma^j, g = w exp(a2 sigma) per center, g_b without its exp (carried by g_a)
      real(wp) :: g_a(0:4), g_b(0:4)
      !> Common subexpressions of the radial jets
      real(wp) :: fj0, fj1, fj2, fj3, fj4, fj5, fj6, fj7, fj8

      if (.not. fade_width > 0.0_wp) error stop &
         "cfc_pair_radius_eval: fade_width must be positive"
      band_end = fade_start + fade_width
      ! Beyond the band of a center: w = 0, nothing to add
      if (sg_a >= band_end .or. sg_b >= band_end) return
      inv_delta = 1.0_wp/fade_width
      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7

            sr = (band_end - (sg_a))*inv_delta
            fs = min(max(sr, 0.0_wp), 1.0_wp)
            ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
            dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
            fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
            fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
            fsp1 = fs
            fsp2 = fsp1*fs
            fsp3 = fsp2*fs
            fsp4 = fsp3*fs
            fsp5 = fsp4*fs
            fu = exp(a2*(sg_a + sg_b))
            fj0 = fp0*fsp5
            g_a(0) = fj0*fu
            g_a(1) = fu*(a2*fj0 + dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5))
            sr = (band_end - (sg_b))*inv_delta
            fs = min(max(sr, 0.0_wp), 1.0_wp)
            ft = min(max((sg_b - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
            dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
            fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
            fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
            fsp1 = fs
            fsp2 = fsp1*fs
            fsp3 = fsp2*fs
            fsp4 = fsp3*fs
            fsp5 = fsp4*fs
            fj0 = fp0*fsp5
            g_b(0) = fj0
            g_b(1) = a2*fj0 + dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
            x0 = 1.0_wp/R_a
            x1 = 1.0_wp/R_b
            x2 = d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)
            x3 = -x0*x1*x2 + 1.0_wp
            x4 = c_par*(x3*x3*x3*x3)
            x5 = 1.0_wp/(R_a*R_a)
            x6 = (x3*x3*x3)
            x7 = 1.0_wp/(R_b*R_b)
            rd0_a = &
               rd0_a + (4.0_wp*c_par*g_a(0)*g_b(0)*x1*x2*x5*x6 - &
               g_a(1)*g_b(0)*x4*x5*sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3)))))
            rd0_b = &
               rd0_b + (4.0_wp*c_par*g_a(0)*g_b(0)*x0*x2*x6*x7 - &
               g_a(0)*g_b(1)*x4*x7*sqrt(((d_b(1)*d_b(1)) + (d_b(2)*d_b(2)) + (d_b(3)*d_b(3)))))
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
            real(wp) :: x62, x63, x64, x65, x66, x67, x68, x69, x70, x71, x72, x73, x74

            sr = (band_end - (sg_a))*inv_delta
            fs = min(max(sr, 0.0_wp), 1.0_wp)
            ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
            dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
            fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
            fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
            fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
            fsp1 = fs
            fsp2 = fsp1*fs
            fsp3 = fsp2*fs
            fsp4 = fsp3*fs
            fsp5 = fsp4*fs
            fu = exp(a2*(sg_a + sg_b))
            fj0 = fp0*fsp5
            fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
            g_a(0) = fj0*fu
            g_a(1) = fu*(a2*fj0 + fj1)
            g_a(2) = &
               fu*((a2*a2)*fj0 + 2.0_wp*a2*fj1 + (dsdd*dsdd)*fsp3*(20.0_wp*fp0 + 10.0_wp*fp1*fs + &
               fp2*fsp2))
            sr = (band_end - (sg_b))*inv_delta
            fs = min(max(sr, 0.0_wp), 1.0_wp)
            ft = min(max((sg_b - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
            dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
            fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
            fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
            fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
            fsp1 = fs
            fsp2 = fsp1*fs
            fsp3 = fsp2*fs
            fsp4 = fsp3*fs
            fsp5 = fsp4*fs
            fj0 = fp0*fsp5
            fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
            g_b(0) = fj0
            g_b(1) = a2*fj0 + fj1
            g_b(2) = &
               (a2*a2)*fj0 + 2.0_wp*a2*fj1 + (dsdd*dsdd)*fsp3*(20.0_wp*fp0 + 10.0_wp*fp1*fs + &
               fp2*fsp2)
            x0 = sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))))
            x1 = g_a(1)*x0
            x2 = 1.0_wp/(R_a*R_a)
            x3 = 1.0_wp/R_a
            x4 = 1.0_wp/R_b
            x5 = d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)
            x6 = x4*x5
            x7 = -x3*x6 + 1.0_wp
            x8 = c_par*(x7*x7*x7*x7)
            x9 = g_b(0)*x8
            x10 = x2*x9
            x11 = (x7*x7*x7)
            x12 = sqrt(((d_b(1)*d_b(1)) + (d_b(2)*d_b(2)) + (d_b(3)*d_b(3))))
            x13 = g_b(1)*x12
            x14 = 1.0_wp/(R_b*R_b)
            x15 = g_a(0)*x8
            x16 = x14*x15
            x17 = 1.0_wp/(R_a*R_a*R_a)
            x18 = d_a(1)*x17
            x19 = g_a(2)*x9
            x20 = 4.0_wp*x11
            x21 = x20*x4
            x22 = c_par*g_a(0)*g_b(0)
            x23 = x2*x22
            x24 = d_a(1)*x23
            x25 = x21*x23
            x26 = g_a(1)/x0
            x27 = x10*x26
            x28 = 12.0_wp*(x7*x7)
            x29 = x14*x22*x28*x5
            x30 = d_b(1)*x17
            x31 = c_par*g_b(0)
            x32 = x18*x31
            x33 = x1*x21
            x34 = x31*x33
            x35 = x20*x26*x6
            x36 = g_b(1)/x12
            x37 = x2*x36
            x38 = d_b(1)*x37
            x39 = c_par*g_a(0)
            x40 = x20*x5
            x41 = x14*x39*x40
            x42 = x1*x4*x8
            x43 = x17*x19
            x44 = x17*x29
            x45 = x17*x34
            x46 = d_a(2)*x31
            x47 = x17*x35
            x48 = x37*x41
            x49 = x37*x42
            x50 = d_a(3)*x31
            x51 = 1.0_wp/(R_b*R_b*R_b)
            x52 = d_b(1)*x51
            x53 = g_b(2)*x15
            x54 = x20*x3
            x55 = d_a(1)*x54
            x56 = x14*x22
            x57 = x54*x56
            x58 = x16*x36
            x59 = x28*x5
            x60 = x51*x59
            x61 = x13*x39
            x62 = x51*x61
            x63 = x52*x54
            x64 = x14*x26
            x65 = d_a(1)*x64
            x66 = x2*x40
            x67 = x36*x39*x5
            x68 = x13*x3*x8
            x69 = x51*x53
            x70 = x23*x60
            x71 = x54*x62
            x72 = x64*x66
            x73 = x51*x54*x67
            x74 = x64*x68
            rd0_a = rd0_a + (4.0_wp*c_par*g_a(0)*g_b(0)*x11*x2*x4*x5 - x1*x10)
            rd0_b = rd0_b + (4.0_wp*c_par*g_a(0)*g_b(0)*x11*x14*x3*x5 - x13*x16)
            rd1_r_a(1) = &
               rd1_r_a(1) + (-d_a(1)*x27 + d_b(1)*x25 - x18*x19 - x18*x29 + x21*x24 - x29*x30 + &
               x30*x34 + x32*x33 + x32*x35 + x38*x41 - x38*x42)
            rd1_r_a(2) = &
               rd1_r_a(2) + (d_a(2)*x25 - d_a(2)*x27 - d_a(2)*x43 - d_a(2)*x44 + d_a(2)*x45 + &
               d_b(2)*x25 - d_b(2)*x44 + d_b(2)*x45 + d_b(2)*x48 - d_b(2)*x49 + x46*x47)
            rd1_r_a(3) = &
               rd1_r_a(3) + (d_a(3)*x25 - d_a(3)*x27 - d_a(3)*x43 - d_a(3)*x44 + d_a(3)*x45 + &
               d_b(3)*x25 - d_b(3)*x44 + d_b(3)*x45 + d_b(3)*x48 - d_b(3)*x49 + x47*x50)
            rd1_r_b(1) = &
               rd1_r_b(1) + (d_b(1)*x57 - d_b(1)*x58 - x23*x52*x59 - x24*x60 + x31*x65*x66 - &
               x52*x53 + x55*x56 + x55*x62 + x61*x63 + x63*x67 - x65*x68)
            rd1_r_b(2) = &
               rd1_r_b(2) + (d_a(2)*x57 - d_a(2)*x70 + d_a(2)*x71 - d_a(2)*x74 + d_b(2)*x57 - &
               d_b(2)*x58 - d_b(2)*x69 - d_b(2)*x70 + d_b(2)*x71 + d_b(2)*x73 + x46*x72)
            rd1_r_b(3) = &
               rd1_r_b(3) + (d_a(3)*x57 - d_a(3)*x70 + d_a(3)*x71 - d_a(3)*x74 + d_b(3)*x57 - &
               d_b(3)*x58 - d_b(3)*x69 - d_b(3)*x70 + d_b(3)*x71 + d_b(3)*x73 + x50*x72)
         end block
      case (2)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
            real(wp) :: x62, x63, x64, x65, x66, x67, x68, x69, x70, x71, x72, x73, x74, x75, x76
            real(wp) :: x77, x78, x79, x80, x81, x82, x83, x84, x85, x86, x87, x88, x89, x90, x91
            real(wp) :: x92, x93, x94, x95, x96, x97, x98, x99, x100, x101, x102, x103, x104, x105
            real(wp) :: x106, x107, x108, x109, x110, x111, x112, x113, x114, x115, x116, x117, x118
            real(wp) :: x119, x120, x121, x122, x123, x124, x125, x126, x127, x128, x129, x130, x131
            real(wp) :: x132, x133, x134, x135, x136, x137, x138, x139, x140, x141, x142, x143, x144
            real(wp) :: x145, x146, x147, x148, x149, x150, x151, x152, x153, x154, x155, x156, x157
            real(wp) :: x158, x159, x160, x161, x162, x163, x164, x165, x166, x167, x168, x169, x170
            real(wp) :: x171, x172, x173, x174, x175, x176, x177, x178, x179, x180, x181, x182, x183
            real(wp) :: x184, x185, x186, x187, x188, x189, x190, x191, x192, x193, x194, x195, x196
            real(wp) :: x197, x198, x199, x200, x201, x202, x203, x204, x205, x206, x207, x208, x209
            real(wp) :: x210, x211, x212, x213, t_rd2_rr_a_01, t_rd2_rr_a_02, t_rd2_rr_a_12
            real(wp) :: t_rd2_rr_b_01, t_rd2_rr_b_02, t_rd2_rr_b_12

            sr = (band_end - (sg_a))*inv_delta
            fs = min(max(sr, 0.0_wp), 1.0_wp)
            ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
            dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
            fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
            fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
            fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
            fp3 = -1680.0_wp*ft - 210.0_wp
            fsp1 = fs
            fsp2 = fsp1*fs
            fsp3 = fsp2*fs
            fsp4 = fsp3*fs
            fsp5 = fsp4*fs
            fu = exp(a2*(sg_a + sg_b))
            fj0 = fp0*fsp5
            fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
            fj2 = (a2*a2)
            fj3 = fp2*fsp2
            fj4 = fp1*fs
            fj5 = (dsdd*dsdd)*fsp3*(fj3 + 10.0_wp*fj4 + 20.0_wp*fp0)
            g_a(0) = fj0*fu
            g_a(1) = fu*(a2*fj0 + fj1)
            g_a(2) = fu*(2.0_wp*a2*fj1 + fj0*fj2 + fj5)
            g_a(3) = &
               fu*((a2*a2*a2)*fj0 + 3.0_wp*a2*fj5 + (dsdd*dsdd*dsdd)*fsp2*(15.0_wp*fj3 + &
               60.0_wp*fj4 + 60.0_wp*fp0 + fp3*fsp3) + 3.0_wp*fj1*fj2)
            sr = (band_end - (sg_b))*inv_delta
            fs = min(max(sr, 0.0_wp), 1.0_wp)
            ft = min(max((sg_b - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
            dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
            fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
            fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
            fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
            fp3 = -1680.0_wp*ft - 210.0_wp
            fsp1 = fs
            fsp2 = fsp1*fs
            fsp3 = fsp2*fs
            fsp4 = fsp3*fs
            fsp5 = fsp4*fs
            fj0 = fp0*fsp5
            fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
            fj2 = (a2*a2)
            fj3 = fp2*fsp2
            fj4 = fp1*fs
            fj5 = (dsdd*dsdd)*fsp3*(fj3 + 10.0_wp*fj4 + 20.0_wp*fp0)
            g_b(0) = fj0
            g_b(1) = a2*fj0 + fj1
            g_b(2) = 2.0_wp*a2*fj1 + fj0*fj2 + fj5
            g_b(3) = &
               (a2*a2*a2)*fj0 + 3.0_wp*a2*fj5 + (dsdd*dsdd*dsdd)*fsp2*(15.0_wp*fj3 + 60.0_wp*fj4 + &
